using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Quanlychuoikhachsan.Domain.Entities;

namespace Quanlychuoikhachsan.Infrastructure.Persistence;

/// <summary>Định nghĩa DbSet và ánh xạ các entity sang schema MySQL của khách sạn.</summary>
public sealed class HotelDbContext(DbContextOptions<HotelDbContext> options) : DbContext(options)
{
    public DbSet<TaiKhoan> TaiKhoans => Set<TaiKhoan>();
    public DbSet<VaiTro> VaiTros => Set<VaiTro>();
    public DbSet<Quyen> Quyens => Set<Quyen>();
    public DbSet<TaiKhoanVaiTro> TaiKhoanVaiTros => Set<TaiKhoanVaiTro>();
    public DbSet<VaiTroQuyen> VaiTroQuyens => Set<VaiTroQuyen>();
    public DbSet<ChucVu> ChucVus => Set<ChucVu>();
    public DbSet<NhanVien> NhanViens => Set<NhanVien>();
    public DbSet<KhachHang> KhachHangs => Set<KhachHang>();
    public DbSet<LoaiPhong> LoaiPhongs => Set<LoaiPhong>();
    public DbSet<Phong> Phongs => Set<Phong>();
    public DbSet<DatPhong> DatPhongs => Set<DatPhong>();
    public DbSet<ChiTietDatPhong> ChiTietDatPhongs => Set<ChiTietDatPhong>();
    public DbSet<KhoaLichPhong> KhoaLichPhongs => Set<KhoaLichPhong>();
    public DbSet<GiaDemDatPhong> GiaDemDatPhongs => Set<GiaDemDatPhong>();
    public DbSet<ChinhSachGia> ChinhSachGias => Set<ChinhSachGia>();
    public DbSet<ChinhSachGiaThu> ChinhSachGiaThus => Set<ChinhSachGiaThu>();
    public DbSet<ChiTietChinhSachGia> ChiTietChinhSachGias => Set<ChiTietChinhSachGia>();
    public DbSet<PhuongThucThanhToan> PhuongThucThanhToans => Set<PhuongThucThanhToan>();
    public DbSet<PhieuCoc> PhieuCocs => Set<PhieuCoc>();
    public DbSet<CaLamViec> CaLamViecs => Set<CaLamViec>();
    public DbSet<YeuCauHuyDatPhong> YeuCauHuyDatPhongs => Set<YeuCauHuyDatPhong>();
    public DbSet<HoaDonPhong> HoaDonPhongs => Set<HoaDonPhong>();
    public DbSet<ChiTietHoaDonPhong> ChiTietHoaDonPhongs => Set<ChiTietHoaDonPhong>();
    public DbSet<ApDungCocHoaDon> ApDungCocHoaDons => Set<ApDungCocHoaDon>();
    public DbSet<ThanhToanHoaDonPhong> ThanhToanHoaDonPhongs => Set<ThanhToanHoaDonPhong>();
    public DbSet<YeuCauThanhToanVietQr> YeuCauThanhToanVietQrs => Set<YeuCauThanhToanVietQr>();
    public DbSet<Kho> Khos => Set<Kho>();
    public DbSet<DanhMucHangHoa> DanhMucHangHoas => Set<DanhMucHangHoa>();
    public DbSet<NhaCungCap> NhaCungCaps => Set<NhaCungCap>();
    public DbSet<NhomHang> NhomHangs => Set<NhomHang>();
    public DbSet<DonViTinh> DonViTinhs => Set<DonViTinh>();
    public DbSet<PhieuNhap> PhieuNhaps => Set<PhieuNhap>();
    public DbSet<ChiTietPhieuNhap> ChiTietPhieuNhaps => Set<ChiTietPhieuNhap>();
    public DbSet<LoHang> LoHangs => Set<LoHang>();
    public DbSet<PhieuXuat> PhieuXuats => Set<PhieuXuat>();
    public DbSet<ChiTietPhieuXuat> ChiTietPhieuXuats => Set<ChiTietPhieuXuat>();
    public DbSet<GiaoDichKho> GiaoDichKhos => Set<GiaoDichKho>();
    public DbSet<TaiSanCaThe> TaiSanCaThes => Set<TaiSanCaThe>();
    public DbSet<TinhTrangPhong> TinhTrangPhongs => Set<TinhTrangPhong>();
    public DbSet<CongViecBuongPhong> CongViecBuongPhongs => Set<CongViecBuongPhong>();
    public DbSet<NhatKyHeThong> NhatKyHeThongs => Set<NhatKyHeThong>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);
        OperationalModel.Configure(modelBuilder);
        modelBuilder.UseCollation("utf8mb4_unicode_ci");
        // Tách ánh xạ theo phân hệ để khớp tên bảng/cột của script MySQL.
        ConfigureAccount(modelBuilder);
        ConfigureHotel(modelBuilder);
        ConfigureBooking(modelBuilder);
        ConfigurePricing(modelBuilder);
        ConfigurePayment(modelBuilder);
        ConfigureBilling(modelBuilder);
        ConfigureVietQrPaymentOrders(modelBuilder);
        ConfigureInventory(modelBuilder);
        modelBuilder.Entity<NhatKyHeThong>(e =>
        {
            e.ToTable("nhat_ky_he_thong");
            e.HasKey(x => x.Id);
            e.Property(x => x.TaiKhoanId).HasColumnName("tai_khoan_id");
            e.Property(x => x.HanhDong).HasColumnName("hanh_dong").HasMaxLength(100).IsRequired();
            e.Property(x => x.DoiTuong).HasColumnName("doi_tuong").HasMaxLength(100);
            e.Property(x => x.DoiTuongId).HasColumnName("doi_tuong_id").HasMaxLength(100);
            e.Property(x => x.DuLieuCu).HasColumnName("du_lieu_cu");
            e.Property(x => x.DuLieuMoi).HasColumnName("du_lieu_moi");
            e.Property(x => x.DiaChiIp).HasColumnName("dia_chi_ip").HasMaxLength(64);
            e.Property(x => x.UserAgent).HasColumnName("user_agent").HasMaxLength(500);
            e.Property(x => x.CreatedAt).HasColumnName("created_at").HasDefaultValueSql("CURRENT_TIMESTAMP");
            e.HasIndex(x => x.TaiKhoanId).HasDatabaseName("idx_nk_tk");
            e.HasIndex(x => new { x.DoiTuong, x.DoiTuongId }).HasDatabaseName("idx_nk_dt");
            e.HasOne<TaiKhoan>().WithMany().HasForeignKey(x => x.TaiKhoanId).OnDelete(DeleteBehavior.SetNull);
        });
        foreach (var entityType in modelBuilder.Model.GetEntityTypes())
        {
            entityType.FindProperty("Id")?.SetColumnName("id");
        }
    }

    // Ánh xạ đơn QR và mã giao dịch duy nhất để đối soát idempotent với ledger hóa đơn.
    private static void ConfigureVietQrPaymentOrders(ModelBuilder b)
    {
        b.Entity<YeuCauThanhToanVietQr>(e =>
        {
            e.ToTable("vietqr_payment_order", t =>
                t.HasCheckConstraint("ck_vietqr_payment_order_amount", "so_tien > 0"));
            e.HasKey(x => x.Id);
            e.Property(x => x.OrderId).HasColumnName("order_id").HasMaxLength(80).IsRequired();
            e.Property(x => x.HoaDonPhongId).HasColumnName("hoa_don_phong_id");
            e.Property(x => x.SoTien).HasColumnName("so_tien").HasPrecision(15, 2);
            e.Property(x => x.NoiDung).HasColumnName("noi_dung").HasMaxLength(100).IsRequired();
            e.Property(x => x.QrCode).HasColumnName("qr_code").HasColumnType("longtext").IsRequired();
            e.Property(x => x.QrDataUrl).HasColumnName("qr_data_url").HasColumnType("longtext").IsRequired();
            e.Property(x => x.TrangThai).HasColumnName("trang_thai").HasMaxLength(30).IsRequired();
            e.Property(x => x.MaGiaoDich).HasColumnName("ma_giao_dich").HasMaxLength(150);
            e.Property(x => x.TransactionDateTime).HasColumnName("transaction_date_time").HasMaxLength(40);
            e.Property(x => x.GhiChu).HasColumnName("ghi_chu").HasMaxLength(1000);
            e.Property(x => x.TaiKhoanTaoId).HasColumnName("tai_khoan_tao_id");
            e.Property(x => x.CreatedAt).HasColumnName("created_at").HasDefaultValueSql("CURRENT_TIMESTAMP");
            e.Property(x => x.UpdatedAt).HasColumnName("updated_at").HasDefaultValueSql("CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP");
            e.Property(x => x.PaidAt).HasColumnName("paid_at");
            e.HasIndex(x => x.OrderId).IsUnique().HasDatabaseName("uq_vietqr_order_id");
            e.HasIndex(x => x.MaGiaoDich).IsUnique().HasDatabaseName("uq_vietqr_transaction_id");
            e.HasIndex(x => new { x.HoaDonPhongId, x.TrangThai }).HasDatabaseName("idx_vietqr_invoice_status");
            e.HasOne<HoaDonPhong>().WithMany().HasForeignKey(x => x.HoaDonPhongId).OnDelete(DeleteBehavior.Restrict);
            e.HasOne<TaiKhoan>().WithMany().HasForeignKey(x => x.TaiKhoanTaoId).OnDelete(DeleteBehavior.SetNull);
        });
    }

    private static void ConfigureAccount(ModelBuilder b)
    {
        b.Entity<TaiKhoan>(e =>
        {
            e.ToTable("tai_khoan", t => t.HasCheckConstraint("ck_tk_contact", "email IS NOT NULL OR so_dien_thoai IS NOT NULL"));
            e.HasKey(x => x.Id); e.Property(x => x.Id).HasColumnName("id");
            e.Property(x => x.Email).HasColumnName("email").HasMaxLength(150);
            e.Property(x => x.SoDienThoai).HasColumnName("so_dien_thoai").HasMaxLength(20);
            e.Property(x => x.MatKhauHash).HasColumnName("mat_khau_hash").HasMaxLength(255).IsRequired();
            e.Property(x => x.LoaiTaiKhoan).HasColumnName("loai_tai_khoan").HasMaxLength(20).IsRequired();
            e.Property(x => x.TrangThai).HasColumnName("trang_thai").HasMaxLength(30).HasDefaultValue("HOAT_DONG");
            e.Property(x => x.EmailDaXacThuc).HasColumnName("email_da_xac_thuc");
            e.Property(x => x.LanDangNhapCuoi).HasColumnName("lan_dang_nhap_cuoi");
            e.Property(x => x.CreatedAt).HasColumnName("created_at").HasDefaultValueSql("CURRENT_TIMESTAMP");
            e.Property(x => x.UpdatedAt).HasColumnName("updated_at").HasDefaultValueSql("CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP");
            e.HasIndex(x => x.Email).IsUnique().HasDatabaseName("uq_tk_email");
            e.HasIndex(x => x.SoDienThoai).IsUnique().HasDatabaseName("uq_tk_sdt");
        });
        b.Entity<VaiTro>(e => MapCommon(e, "vai_tro"));
        b.Entity<VaiTro>(e => { e.Property(x => x.MaVaiTro).HasColumnName("ma_vai_tro").HasMaxLength(50).IsRequired(); e.Property(x => x.TenVaiTro).HasColumnName("ten_vai_tro").HasMaxLength(100).IsRequired(); e.Property(x => x.MoTa).HasColumnName("mo_ta").HasMaxLength(500); e.Property(x => x.TrangThai).HasColumnName("trang_thai").HasMaxLength(20); e.HasIndex(x => x.MaVaiTro).IsUnique(); });
        b.Entity<Quyen>(e => { e.ToTable("quyen"); e.HasKey(x => x.Id); e.Property(x => x.MaQuyen).HasColumnName("ma_quyen").HasMaxLength(80).IsRequired(); e.Property(x => x.TenQuyen).HasColumnName("ten_quyen").HasMaxLength(150).IsRequired(); e.Property(x => x.NhomQuyen).HasColumnName("nhom_quyen").HasMaxLength(80); e.Property(x => x.MoTa).HasColumnName("mo_ta").HasMaxLength(500); e.HasIndex(x => x.MaQuyen).IsUnique(); });
        b.Entity<TaiKhoanVaiTro>(e => { e.ToTable("tai_khoan_vai_tro"); e.Property(x => x.TaiKhoanId).HasColumnName("tai_khoan_id"); e.Property(x => x.VaiTroId).HasColumnName("vai_tro_id"); e.HasKey(x => new { x.TaiKhoanId, x.VaiTroId }); e.HasOne(x => x.TaiKhoan).WithMany(x => x.TaiKhoanVaiTros).HasForeignKey(x => x.TaiKhoanId).OnDelete(DeleteBehavior.Cascade); e.HasOne(x => x.VaiTro).WithMany(x => x.TaiKhoanVaiTros).HasForeignKey(x => x.VaiTroId).OnDelete(DeleteBehavior.Cascade); });
        b.Entity<VaiTroQuyen>(e => { e.ToTable("vai_tro_quyen"); e.Property(x => x.VaiTroId).HasColumnName("vai_tro_id"); e.Property(x => x.QuyenId).HasColumnName("quyen_id"); e.HasKey(x => new { x.VaiTroId, x.QuyenId }); e.HasOne(x => x.VaiTro).WithMany(x => x.VaiTroQuyens).HasForeignKey(x => x.VaiTroId).OnDelete(DeleteBehavior.Cascade); e.HasOne(x => x.Quyen).WithMany(x => x.VaiTroQuyens).HasForeignKey(x => x.QuyenId).OnDelete(DeleteBehavior.Cascade); });
        b.Entity<ChucVu>(e => { e.ToTable("chuc_vu"); e.HasKey(x => x.Id); e.Property(x => x.MaChucVu).HasColumnName("ma_chuc_vu").HasMaxLength(30).IsRequired(); e.Property(x => x.TenChucVu).HasColumnName("ten_chuc_vu").HasMaxLength(100).IsRequired(); e.Property(x => x.MoTa).HasColumnName("mo_ta").HasMaxLength(500); e.Property(x => x.TrangThai).HasColumnName("trang_thai").HasMaxLength(20).HasDefaultValue("HOAT_DONG"); e.HasIndex(x => x.MaChucVu).IsUnique(); });
        b.Entity<NhanVien>(e => { e.ToTable("nhan_vien"); e.HasKey(x => x.Id); MapProperties(e); e.Property(x => x.MaNhanVien).HasColumnName("ma_nhan_vien").HasMaxLength(30).IsRequired(); e.Property(x => x.TaiKhoanId).HasColumnName("tai_khoan_id"); e.Property(x => x.ChucVuId).HasColumnName("chuc_vu_id"); e.Property(x => x.HoTen).HasColumnName("ho_ten").HasMaxLength(120).IsRequired(); e.Property(x => x.NgaySinh).HasColumnName("ngay_sinh"); e.Property(x => x.GioiTinh).HasColumnName("gioi_tinh").HasMaxLength(20); e.Property(x => x.SoDienThoai).HasColumnName("so_dien_thoai").HasMaxLength(20); e.Property(x => x.Email).HasColumnName("email").HasMaxLength(150); e.Property(x => x.CccdHoChieu).HasColumnName("cccd_ho_chieu").HasMaxLength(40); e.Property(x => x.DiaChi).HasColumnName("dia_chi").HasMaxLength(255); e.Property(x => x.NgayVaoLam).HasColumnName("ngay_vao_lam"); e.Property(x => x.TrangThai).HasColumnName("trang_thai").HasMaxLength(30); e.Property(x => x.CreatedAt).HasColumnName("created_at"); e.HasIndex(x => x.MaNhanVien).IsUnique(); e.HasIndex(x => x.TaiKhoanId).IsUnique(); e.HasOne(x => x.TaiKhoan).WithOne(x => x.NhanVien).HasForeignKey<NhanVien>(x => x.TaiKhoanId).OnDelete(DeleteBehavior.Restrict); e.HasOne(x => x.ChucVu).WithMany(x => x.NhanViens).HasForeignKey(x => x.ChucVuId).OnDelete(DeleteBehavior.Restrict); });
        b.Entity<KhachHang>(e => { e.ToTable("khach_hang"); e.HasKey(x => x.Id); MapProperties(e); e.Property(x => x.MaKhachHang).HasColumnName("ma_khach_hang").HasMaxLength(30).IsRequired(); e.Property(x => x.TaiKhoanId).HasColumnName("tai_khoan_id"); e.Property(x => x.HoTen).HasColumnName("ho_ten").HasMaxLength(120).IsRequired(); e.Property(x => x.NgaySinh).HasColumnName("ngay_sinh"); e.Property(x => x.GioiTinh).HasColumnName("gioi_tinh").HasMaxLength(20); e.Property(x => x.SoDienThoai).HasColumnName("so_dien_thoai").HasMaxLength(20); e.Property(x => x.Email).HasColumnName("email").HasMaxLength(150); e.Property(x => x.CccdHoChieu).HasColumnName("cccd_ho_chieu").HasMaxLength(40); e.Property(x => x.DiaChi).HasColumnName("dia_chi").HasMaxLength(255); e.Property(x => x.GhiChu).HasColumnName("ghi_chu").HasMaxLength(500); e.Property(x => x.CreatedAt).HasColumnName("created_at"); e.Property(x => x.UpdatedAt).HasColumnName("updated_at"); e.HasIndex(x => x.MaKhachHang).IsUnique(); e.HasIndex(x => x.TaiKhoanId).IsUnique(); e.HasIndex(x => x.SoDienThoai).HasDatabaseName("idx_kh_sdt"); e.HasIndex(x => x.Email).HasDatabaseName("idx_kh_email"); e.HasOne(x => x.TaiKhoan).WithOne(x => x.KhachHang).HasForeignKey<KhachHang>(x => x.TaiKhoanId).OnDelete(DeleteBehavior.SetNull); });
    }

    private static void ConfigureHotel(ModelBuilder b)
    {
        b.Entity<LoaiPhong>(e => { e.ToTable("loai_phong", t => t.HasCheckConstraint("ck_lp_base_price", "gia_co_ban_dem >= 0")); e.HasKey(x => x.Id); e.Property(x => x.MaLoaiPhong).HasColumnName("ma_loai_phong").HasMaxLength(30).IsRequired(); e.Property(x => x.TenLoaiPhong).HasColumnName("ten_loai_phong").HasMaxLength(100).IsRequired(); e.Property(x => x.SoNguoiLonToiDa).HasColumnName("so_nguoi_lon_toi_da"); e.Property(x => x.SoTreEmToiDa).HasColumnName("so_tre_em_toi_da"); e.Property(x => x.DienTichM2).HasColumnName("dien_tich_m2").HasPrecision(8, 2); e.Property(x => x.GiaCoBanDem).HasColumnName("gia_co_ban_dem").HasPrecision(15, 2); e.Property(x => x.MoTa).HasColumnName("mo_ta"); e.Property(x => x.TrangThai).HasColumnName("trang_thai").HasMaxLength(20); e.HasIndex(x => x.MaLoaiPhong).IsUnique(); });
        b.Entity<Phong>(e => { e.ToTable("phong", t => t.HasCheckConstraint("ck_phong_surcharge", "phu_thu_dem_mac_dinh >= 0")); e.HasKey(x => x.Id); e.Property(x => x.MaPhong).HasColumnName("ma_phong").HasMaxLength(30).IsRequired(); e.Property(x => x.LoaiPhongId).HasColumnName("loai_phong_id"); e.Property(x => x.SoPhong).HasColumnName("so_phong").HasMaxLength(20).IsRequired(); e.Property(x => x.Tang).HasColumnName("tang").HasMaxLength(20); e.Property(x => x.HuongPhong).HasColumnName("huong_phong").HasMaxLength(80); e.Property(x => x.LoaiView).HasColumnName("loai_view").HasMaxLength(100); e.Property(x => x.ViTri).HasColumnName("vi_tri").HasMaxLength(150); e.Property(x => x.PhuThuDemMacDinh).HasColumnName("phu_thu_dem_mac_dinh").HasPrecision(15, 2); e.Property(x => x.TrangThai).HasColumnName("trang_thai").HasMaxLength(30); e.Property(x => x.MoTa).HasColumnName("mo_ta").HasMaxLength(1000); e.Property(x => x.GhiChu).HasColumnName("ghi_chu").HasMaxLength(500); e.HasIndex(x => x.MaPhong).IsUnique(); e.HasIndex(x => x.SoPhong).IsUnique(); e.HasOne(x => x.LoaiPhong).WithMany(x => x.Phongs).HasForeignKey(x => x.LoaiPhongId).OnDelete(DeleteBehavior.Restrict); });
    }

    private static void ConfigureBooking(ModelBuilder b)
    {
        b.Entity<DatPhong>(e => { e.ToTable("dat_phong", t => t.HasCheckConstraint("ck_dp_dates", "du_kien_tra > du_kien_nhan")); e.HasKey(x => x.Id); e.Property(x => x.MaDatPhong).HasColumnName("ma_dat_phong").HasMaxLength(40).IsRequired(); e.Property(x => x.KhachHangId).HasColumnName("khach_hang_id"); e.Property(x => x.TaiKhoanTaoId).HasColumnName("tai_khoan_tao_id"); e.Property(x => x.NgayDat).HasColumnName("ngay_dat"); e.Property(x => x.DuKienNhan).HasColumnName("du_kien_nhan"); e.Property(x => x.DuKienTra).HasColumnName("du_kien_tra"); e.Property(x => x.SoNguoiLon).HasColumnName("so_nguoi_lon"); e.Property(x => x.SoTreEm).HasColumnName("so_tre_em"); e.Property(x => x.KenhDat).HasColumnName("kenh_dat").HasMaxLength(30); e.Property(x => x.TrangThai).HasColumnName("trang_thai").HasMaxLength(30); e.Property(x => x.YeuCauDacBiet).HasColumnName("yeu_cau_dac_biet").HasMaxLength(1000); e.Property(x => x.TongTienPhongGoc).HasColumnName("tong_tien_phong_goc").HasPrecision(15, 2); e.Property(x => x.TongTienDuKien).HasColumnName("tong_tien_du_kien").HasPrecision(15, 2); e.Property(x => x.CreatedAt).HasColumnName("created_at"); e.Property(x => x.UpdatedAt).HasColumnName("updated_at"); e.HasIndex(x => x.MaDatPhong).IsUnique(); e.HasIndex(x => new { x.DuKienNhan, x.DuKienTra }).HasDatabaseName("idx_dp_time"); e.HasOne(x => x.KhachHang).WithMany(x => x.DatPhongs).HasForeignKey(x => x.KhachHangId).OnDelete(DeleteBehavior.Restrict); e.HasOne<TaiKhoan>().WithMany().HasForeignKey(x => x.TaiKhoanTaoId).OnDelete(DeleteBehavior.SetNull); });
        b.Entity<ChiTietDatPhong>(e => { e.ToTable("chi_tiet_dat_phong"); e.HasKey(x => x.Id); e.Property(x => x.DatPhongId).HasColumnName("dat_phong_id"); e.Property(x => x.PhongId).HasColumnName("phong_id"); e.Property(x => x.SoNguoiLon).HasColumnName("so_nguoi_lon"); e.Property(x => x.SoTreEm).HasColumnName("so_tre_em"); e.Property(x => x.TienPhongDuKien).HasColumnName("tien_phong_du_kien").HasPrecision(15, 2); e.Property(x => x.NhanPhongLuc).HasColumnName("nhan_phong_luc"); e.Property(x => x.TraPhongLuc).HasColumnName("tra_phong_luc"); e.Property(x => x.TrangThai).HasColumnName("trang_thai").HasMaxLength(30); e.Property(x => x.GhiChu).HasColumnName("ghi_chu").HasMaxLength(500); e.HasIndex(x => new { x.DatPhongId, x.PhongId }).IsUnique().HasDatabaseName("uq_booking_room"); e.HasOne(x => x.DatPhong).WithMany(x => x.ChiTietDatPhongs).HasForeignKey(x => x.DatPhongId).OnDelete(DeleteBehavior.Cascade); e.HasOne(x => x.Phong).WithMany(x => x.ChiTietDatPhongs).HasForeignKey(x => x.PhongId).OnDelete(DeleteBehavior.Restrict); });
        b.Entity<KhoaLichPhong>(e => { e.ToTable("khoa_lich_phong"); e.HasKey(x => x.Id); e.Property(x => x.ChiTietDatPhongId).HasColumnName("chi_tiet_dat_phong_id"); e.Property(x => x.PhongId).HasColumnName("phong_id"); e.Property(x => x.NgayLuuTru).HasColumnName("ngay_luu_tru"); e.Property(x => x.TrangThai).HasColumnName("trang_thai").HasMaxLength(20); e.Property(x => x.HetHanGiuCho).HasColumnName("het_han_giu_cho"); e.Property(x => x.CreatedAt).HasColumnName("created_at"); e.HasIndex(x => new { x.PhongId, x.NgayLuuTru }).IsUnique().HasDatabaseName("uq_room_day"); e.HasIndex(x => new { x.ChiTietDatPhongId, x.NgayLuuTru }).IsUnique().HasDatabaseName("uq_detail_day"); e.HasOne<ChiTietDatPhong>().WithMany().HasForeignKey(x => x.ChiTietDatPhongId).OnDelete(DeleteBehavior.Cascade); e.HasOne<Phong>().WithMany().HasForeignKey(x => x.PhongId).OnDelete(DeleteBehavior.Restrict); });
        b.Entity<GiaDemDatPhong>(e => { e.ToTable("gia_dem_dat_phong"); e.HasKey(x => x.Id); e.Property(x => x.ChiTietDatPhongId).HasColumnName("chi_tiet_dat_phong_id"); e.Property(x => x.NgayLuuTru).HasColumnName("ngay_luu_tru"); e.Property(x => x.GiaCoBan).HasColumnName("gia_co_ban").HasPrecision(15, 2); e.Property(x => x.PhuThuPhong).HasColumnName("phu_thu_phong").HasPrecision(15, 2); e.Property(x => x.ChinhSachGiaId).HasColumnName("chinh_sach_gia_id"); e.Property(x => x.TienDieuChinh).HasColumnName("tien_dieu_chinh").HasPrecision(15, 2); e.Property(x => x.GiaSauDieuChinh).HasColumnName("gia_sau_dieu_chinh").HasPrecision(15, 2); e.HasIndex(x => new { x.ChiTietDatPhongId, x.NgayLuuTru }).IsUnique().HasDatabaseName("uq_price_night"); e.HasOne<ChiTietDatPhong>().WithMany().HasForeignKey(x => x.ChiTietDatPhongId).OnDelete(DeleteBehavior.Cascade); e.HasOne<ChinhSachGia>().WithMany().HasForeignKey(x => x.ChinhSachGiaId).OnDelete(DeleteBehavior.SetNull); });
    }

    private static void ConfigurePricing(ModelBuilder b)
    {
