    private static void MapMoney<TEntity>(EntityTypeBuilder<TEntity> e, System.Linq.Expressions.Expression<Func<TEntity, decimal>> p, string name) where TEntity : class => e.Property(p).HasColumnName(name).HasPrecision(15, 2);
    private static void MapQty<TEntity>(EntityTypeBuilder<TEntity> e, System.Linq.Expressions.Expression<Func<TEntity, decimal>> p, string name) where TEntity : class => e.Property(p).HasColumnName(name).HasPrecision(15, 3);

    private static void MapCommon<TEntity>(EntityTypeBuilder<TEntity> e, string table) where TEntity : EntityBase
    { e.ToTable(table); e.HasKey(x => x.Id); }
    private static void MapProperties<TEntity>(EntityTypeBuilder<TEntity> e) where TEntity : EntityBase
    { e.Property(x => x.Id).HasColumnName("id"); }
